mapper.update:
UPDATE product
SET name = #{name}, category_id = #{categoryId}, status = #{status},
    price = #{price}, warn_threshold = #{warnThreshold}
WHERE id = #{id}

UPDATE product
SET stock = stock - #{quantity}, updated_at = NOW()
WHERE id = #{productId} AND deleted = 0 AND stock >= #{quantity}
